1197	/* 轮询：扫描完成 → 重建清单；连接状态变化 → 更新状态/保存配置 */
1198	static void wifi_poll_cb(lv_timer_t *timer)
1199	{
1200	    (void)timer;
1201	
1202	    /* 扫描失败（驱动忙/超时）：提示重试，避免永远卡"扫描中…" */
1203	    if (dm_net_wifi_scan_failed() && wifi_status_lbl) {
1204	        lv_label_set_text(wifi_status_lbl, "扫描失败，请点\"重新扫描\"重试");
1205	    } else if (dm_net_wifi_scan_done() && wifi_list_cont) {
1206	        wifi_rebuild_list();
1207	    }
1208	
1209	    int st = dm_net_wifi_connect_state();
1210	    if (st != wifi_last_conn_state && wifi_status_lbl) {
1211	        if (st == 2) {   /* 连接成功：记住配置 + 刷新状态栏/清单 */
1212	            char cur[33] = {0};
1213	            dm_net_wifi_cur_ssid(cur, sizeof(cur));
1214	            dm_net_wifi_save_conf(cur, NULL);   /* psk 已由 dm_net 线程保存 */
1215	            lv_label_set_text_fmt(wifi_status_lbl, "已连接 %s", cur);
1216	            wifi_rebuild_list();
1217	            dm_net_status_refresh();
1218	        } else if (st == 3) {
1219	            lv_label_set_text(wifi_status_lbl,
1220	                              "连接失败：密码错误或无法连接");
1221	        }
1222	        wifi_last_conn_state = st;
1223	    }
1224	}
