3026	/* 某本书的阅读百分比（书架进度徽章用，0 表示未读） */
3027	static int book_progress_pct(int idx)
3028	{
3029	    if (idx < 0 || idx >= (int)dm_book_count) return 0;
3030	
3031	    long offset = 0;
3032	    FILE *f = fopen(BOOK_PROGRESS_FILE, "r");
3033	    if (f) {
3034	        char line[256];
3035	        while (fgets(line, sizeof(line), f)) {
3036	            char path[160];
3037	            long off;
3038	            if (sscanf(line, "%159[^:]:%ld", path, &off) == 2 &&
3039	                strcmp(path, dm_book_paths[idx]) == 0) {
3040	                offset = off;
3041	                break;
3042	            }
3043	        }
3044	        fclose(f);
3045	    }
3046	    if (offset <= 0) return 0;
3047	
3048	    struct stat st;
3049	    if (stat(dm_book_paths[idx], &st) != 0 || st.st_size <= 0) return 0;
3050	    int pct = (int)(offset * 100 / st.st_size);
3051	    return pct > 100 ? 100 : pct;
3052	}
