3297	static int book_utf8_trim(char *buf, int len)
3298	{
3299	    if (len <= 0) return 0;
3300	    int n = len;
3301	    while (n > 0) {
3302	        unsigned char c = (unsigned char)buf[n - 1];
3303	        if ((c & 0x80) == 0) break;
3304	        if ((c & 0xC0) == 0xC0) break;
3305	        n--;
3306	    }
3307	    buf[n] = '\0';
3308	    return n;
3309	}
