    lv_obj_add_event_cb(book_reader_slider, book_slider_cb,
                        LV_EVENT_VALUE_CHANGED, NULL);

    book_reader_prog = lv_label_create(bar);
    lv_label_set_text(book_reader_prog, "0%");
