3271	/* UTF-8 边界安全截断 */
3272	static int book_utf8_trim(char *buf, int len)
3273	{
3274	    if (len <= 0) return 0;
3275	    int n = len;
3276	    while (n > 0) {
3277	        unsigned char c = (unsigned char)buf[n - 1];
3278	        if ((c & 0x80) == 0) break;
3279	        if ((c & 0xC0) == 0xC0) break;
3280	        n--;
3281	    }
3282	    buf[n] = '\0';
3283	    return n;
3284	}
