2833	static void files_scan_dir(const char *path)
2834	{
2835	    DIR *dir = opendir(path);
2836	    if (!dir) { files_count = 0; return; }
2837	
2838	    files_count = 0;
2839	    struct dirent *ent;
2840	    while ((ent = readdir(dir)) != NULL && files_count < FILES_MAX_ENTRIES) {
2841	        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0) continue;
2842	
2843	        char full[256];
2844	        snprintf(full, sizeof(full), "%s/%s", path, ent->d_name);
2845	
2846	        struct stat st;
2847	        if (stat(full, &st) != 0) continue;
2848	
2849	        int type = S_ISDIR(st.st_mode) ? FILE_TYPE_DIR : file_type_from_name(ent->d_name);
2850	
2851	        strncpy(files_paths[files_count], full, sizeof(files_paths[0]) - 1);
2852	        strncpy(files_names[files_count], ent->d_name, sizeof(files_names[0]) - 1);
2853	        files_types[files_count] = type;
2854	        files_sizes[files_count] = S_ISDIR(st.st_mode) ? 0 : (long)st.st_size;
2855	        files_selected[files_count] = 0;
2856	        files_count++;
2857	    }
2858	    closedir(dir);
2859	
2860	    /* 排序：目录在前、按名称升序（安卓文件管理器默认行为） */
2861	    for (uint32_t i = 1; i < files_count; i++) {
2862	        uint32_t j = i;
2863	        while (j > 0) {
2864	            int a_dir = (files_types[j - 1] == FILE_TYPE_DIR);
2865	            int b_dir = (files_types[j] == FILE_TYPE_DIR);
2866	            int swap = 0;
2867	            if (a_dir != b_dir)            swap = b_dir;          /* 目录优先 */
2868	            else if (strcmp(files_names[j - 1], files_names[j]) > 0) swap = 1; /* 名称升序 */
2869	            if (!swap) break;
2870	
2871	            char tmp_p[256], tmp_n[64];
2872	            int  tmp_t; long tmp_s;
2873	            strcpy(tmp_p, files_paths[j - 1]);   strcpy(files_paths[j - 1], files_paths[j]);   strcpy(files_paths[j], tmp_p);
2874	            strcpy(tmp_n, files_names[j - 1]);   strcpy(files_names[j - 1], files_names[j]);   strcpy(files_names[j], tmp_n);
2875	            tmp_t = files_types[j - 1];          files_types[j - 1] = files_types[j];          files_types[j] = tmp_t;
2876	            tmp_s = files_sizes[j - 1];          files_sizes[j - 1] = files_sizes[j];          files_sizes[j] = tmp_s;
2877	            j--;
2878	        }
2879	    }
2880	}
