3277	static void files_open_file(const char *path, int type)
3278	{
3279	    if (type == FILE_TYPE_TXT) {
3280	        for (uint32_t i = 0; i < dm_book_count; i++)
3281	            if (strcmp(dm_book_paths[i], path) == 0) { book_open_reader(i); return; }
3282	        if (dm_book_count < DM_MAX_BOOKS) {
3283	            strncpy(dm_book_paths[dm_book_count], path, sizeof(dm_book_paths[0]) - 1);
3284	            const char *name = strrchr(path, '/'); name = name ? name + 1 : path;
3285	            const char *dot = strrchr(name, '.');
3286	            int len = dot ? (int)(dot - name) : strlen(name);
3287	            snprintf(dm_book_titles[dm_book_count], sizeof(dm_book_titles[0]), "%.*s", len, name);
3288	            book_open_reader(dm_book_count); dm_book_count++;
3289	        }
3290	    }
3291	}
