/* Phase 1 拆分：蓝牙子页（bt_* 回调/destructor/create_bt_subpage）
 * 已整体搬至 ui/ui_bt.c（ui_bt_create） */

static void create_settings_subpage(lv_obj_t *parent)
{
    /* Scrollable column container */
    lv_obj_set_flex_flow(parent, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_style_pad_row(parent, 4, 0);

    /* iOS-style large title */
    lv_obj_t *big_title = lv_label_create(parent);
    lv_label_set_text(big_title, "Settings");
    lv_obj_set_style_text_font(big_title, FONT_TITLE, 0);
    lv_obj_set_style_text_color(big_title, lv_color_hex(COL_TEXT), 0);
    lv_obj_set_style_pad_bottom(big_title, 12, 0);

    /* ═══════ NETWORK ═══════ */
    settings_section_label(parent, "NETWORK");
    lv_obj_t *net = settings_group_card(parent);
    /* 2026-08-08 接线：初始状态读真实驱动状态（wifi_is_up / bt state） */
    int wifi_up = dm_net_wifi_is_up();
    lv_obj_t *wifi_row = settings_row_switch_cb(net, LV_SYMBOL_WIFI, COL_BLUE,
                                                "WiFi", wifi_up > 0,
                                                settings_wifi_cb);
    /* 点击 WiFi 行（非开关处）→ 进入 WiFi 管理子页（手机式 SSID 清单） */
    lv_obj_add_flag(wifi_row, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_event_cb(wifi_row, settings_wifi_row_open_cb,
                        LV_EVENT_CLICKED, NULL);
    settings_add_separator(net);
    int bt_on = dm_net_bt_is_on();
    lv_obj_t *bt_row = settings_row_switch_cb(net, LV_SYMBOL_BLUETOOTH, COL_BLUE,
                                              "Bluetooth", bt_on, settings_bt_cb);
    /* 点击蓝牙行（非开关处）→ 进入蓝牙管理子页（手机式设备清单） */
    lv_obj_add_flag(bt_row, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_event_cb(bt_row, settings_bt_row_open_cb, LV_EVENT_CLICKED, NULL);

    /* ═══════ DISPLAY & BRIGHTNESS ═══════ */
    settings_section_label(parent, "DISPLAY & BRIGHTNESS");
    lv_obj_t *disp = settings_group_card(parent);
    settings_row_slider(disp, LV_SYMBOL_TINT, COL_BLUE, "Brightness", 75,
                        settings_brightness_cb);
    settings_add_separator(disp);
    lv_obj_t *al_row = settings_row_value(disp, LV_SYMBOL_KEYBOARD, COL_BLUE,
                                          "Auto-Lock", "30 sec", true);
    lv_obj_add_event_cb(al_row, settings_autolock_cb, LV_EVENT_CLICKED, NULL);
    settings_add_separator(disp);
    settings_row_switch(disp, LV_SYMBOL_TINT, COL_PURPLE, "Dark Mode", false);
    settings_add_separator(disp);
    settings_row_switch(disp, LV_SYMBOL_EYE_OPEN, COL_ORANGE, "Night Shift",
                        false);
    settings_add_separator(disp);
    /* Text Size: fonts are freetype-created at fixed sizes; switching them
     * would require rebuilding the whole UI — kept as a display placeholder */
    settings_row_value(disp, LV_SYMBOL_EDIT, COL_BLUE, "Text Size", "Medium",
                       true);

    /* ═══════ SOUND ═══════ */
    settings_section_label(parent, "SOUND");
    lv_obj_t *snd = settings_group_card(parent);
    settings_row_slider(snd, LV_SYMBOL_VOLUME_MAX, COL_RED, "Volume",
                        g_music_volume, settings_volume_cb);
    settings_add_separator(snd);
    settings_row_switch(snd, LV_SYMBOL_BELL, COL_RED, "Notification", true);
    settings_add_separator(snd);
    settings_row_switch(snd, LV_SYMBOL_AUDIO, COL_SEC, "Key Sound", true);
    settings_add_separator(snd);
    settings_row_switch(snd, LV_SYMBOL_MUTE, COL_RED, "Silent Mode", false);

    /* ═══════ GENERAL ═══════ */
    settings_section_label(parent, "GENERAL");
    lv_obj_t *gen = settings_group_card(parent);
    settings_row_value(gen, LV_SYMBOL_KEYBOARD, COL_BLUE, "Language", "English",
                       true);
    settings_add_separator(gen);
    settings_row_value(gen, LV_SYMBOL_REFRESH, COL_BLUE, "Date & Time", "Auto",
                       true);
    settings_add_separator(gen);
    settings_row_value(gen, LV_SYMBOL_KEYBOARD, COL_SEC, "Keyboard", NULL, true);
    settings_add_separator(gen);
    settings_row_value(gen, LV_SYMBOL_EYE_OPEN, COL_BLUE, "Accessibility", NULL,
                       true);

    /* ═══════ STORAGE & BATTERY ═══════ */
    settings_section_label(parent, "STORAGE & BATTERY");
    lv_obj_t *stor = settings_group_card(parent);
    settings_row_value(stor, LV_SYMBOL_SD_CARD, COL_GREEN, "Storage",
                       "12.4 / 32 GB", true);
    settings_add_separator(stor);

    /* Storage bar embedded in a custom row */
    {
        lv_obj_t *bar_row = make_clean_cont(stor);
        lv_obj_set_size(bar_row, lv_pct(100), DM(20));
        lv_obj_set_style_pad_left(bar_row, 40, 0);  /* indent past icon */
        lv_obj_set_style_pad_right(bar_row, 8, 0);
        lv_obj_set_style_pad_bottom(bar_row, 8, 0);

        lv_obj_t *bar = lv_bar_create(bar_row);
        lv_obj_set_size(bar, lv_pct(100), DM(4));
        lv_obj_set_style_radius(bar, DM(2), 0);
        lv_obj_set_style_bg_color(bar, lv_color_hex(0x000000), 0);
        lv_obj_set_style_bg_opa(bar, LV_OPA_10, 0);
        lv_obj_set_style_bg_color(bar, lv_color_hex(COL_BLUE), LV_PART_INDICATOR);
        lv_obj_set_style_radius(bar, DM(2), LV_PART_INDICATOR);
        lv_bar_set_range(bar, 0, 100);
        lv_bar_set_value(bar, 39, LV_ANIM_OFF);
        lv_obj_align(bar, LV_ALIGN_LEFT_MID, 0, 0);
    }

    settings_add_separator(stor);
    settings_row_value(stor, LV_SYMBOL_CHARGE, COL_GREEN, "Battery", "87%",
                       false);
    settings_add_separator(stor);
    settings_row_switch(stor, LV_SYMBOL_POWER, COL_GREEN, "Power Saving",
                        false);

    /* ═══════ ABOUT ═══════ */
    settings_section_label(parent, "ABOUT");
    lv_obj_t *about = settings_group_card(parent);
    settings_row_value(about, LV_SYMBOL_HOME, COL_BLUE, "Device Name",
                       "Vela Pad", false);
    settings_add_separator(about);
    settings_row_value(about, LV_SYMBOL_SETTINGS, COL_SEC, "Software",
                       "Vela OS 1.0", false);
    settings_add_separator(about);
    settings_row_value(about, LV_SYMBOL_WARNING, COL_SEC, "Model", "DM-8000",
                       false);
    settings_add_separator(about);
    settings_row_value(about, LV_SYMBOL_LIST, COL_SEC, "Serial", "VL240724X",
                       false);
    settings_add_separator(about);
    settings_row_value(about, LV_SYMBOL_DOWNLOAD, COL_RED, "Software Update",
                       "Up to date", true);

    /* Bottom padding for scroll comfort */
    lv_obj_t *bottom_pad = make_clean_cont(parent);
    lv_obj_set_size(bottom_pad, DM(1), DM(24));
}

