2212	static void cv_fill_circle(lv_obj_t *cv, int cx, int cy, int r, uint32_t color)
2213	{
2214	    for (int dy = -r; dy <= r; dy++)
2215	        for (int dx = -r; dx <= r; dx++)
2216	            if (dx * dx + dy * dy <= r * r)
2217	                cv_px(cv, cx + dx, cy + dy, color);
2218	}
