2220	static void cv_line(lv_obj_t *cv, int x0, int y0, int x1, int y1, uint32_t color)
2221	{
2222	    int dx = x1 > x0 ? x1 - x0 : x0 - x1;
2223	    int dy = y1 > y0 ? y1 - y0 : y0 - y1;
2224	    int sx = x0 < x1 ? 1 : -1;
2225	    int sy = y0 < y1 ? 1 : -1;
2226	    int err = dx - dy;
2227	    while (1)
2228	        {
2229	            cv_px(cv, x0, y0, color);
2230	            if (x0 == x1 && y0 == y1)
2231	                break;
2232	            int e2 = 2 * err;
2233	            if (e2 > -dy) { err -= dy; x0 += sx; }
2234	            if (e2 < dx)  { err += dx; y0 += sy; }
2235	        }
2236	}
