/* ================================================================
 * STATUS BAR — thin top bar with clock, weather, icons
 * ================================================================ */

static void create_status_bar(lv_obj_t *bar)
{
    /* bar is already created by caller, just populate it */
    lv_obj_set_flex_flow(bar, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(bar, LV_FLEX_ALIGN_SPACE_BETWEEN,
                          LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_left(bar, EDGE_PAD, 0);
    lv_obj_set_style_pad_right(bar, EDGE_PAD, 0);

    /* Left: clock — FONT_TITLE, same size as the center big clock */
    clock_label = lv_label_create(bar);
    lv_label_set_text(clock_label, "00:00");
    lv_obj_set_style_text_color(clock_label, lv_color_hex(COL_TEXT), 0);
    lv_obj_set_style_text_font(clock_label, FONT_TITLE, 0);
    lv_obj_set_style_text_letter_space(clock_label, 2, 0);

    /* Center: weather — FONT_ICON, black text for readability */
    status_weather_label = lv_label_create(bar);
    lv_label_set_text(status_weather_label, "21\xc2\xb0""C  |  65%");
    lv_obj_set_style_text_color(status_weather_label, lv_color_hex(COL_TEXT), 0);
    lv_obj_set_style_text_font(status_weather_label, FONT_ICON, 0);

    /* Right: icon row */
    lv_obj_t *icons = make_clean_cont(bar);
    lv_obj_set_size(icons, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(icons, LV_FLEX_FLOW_ROW);
    lv_obj_set_style_pad_column(icons, 16, 0);
    lv_obj_set_flex_align(icons, LV_FLEX_ALIGN_END, LV_FLEX_ALIGN_CENTER,
                          LV_FLEX_ALIGN_CENTER);

    lv_obj_t *wifi = lv_label_create(icons);
    lv_label_set_text(wifi, LV_SYMBOL_WIFI);
    lv_obj_set_style_text_color(wifi, lv_color_hex(COL_SEC), 0);
    lv_obj_set_style_text_font(wifi, FONT_ICON, 0);
    status_wifi_lbl = wifi;

    lv_obj_t *bt = lv_label_create(icons);
    lv_label_set_text(bt, LV_SYMBOL_BLUETOOTH);
    lv_obj_set_style_text_color(bt, lv_color_hex(COL_SEC), 0);
    lv_obj_set_style_text_font(bt, FONT_ICON, 0);
    status_bt_lbl = bt;

    lv_obj_t *bat = lv_label_create(icons);
    lv_label_set_text(bat, LV_SYMBOL_BATTERY_FULL);
    lv_obj_set_style_text_color(bat, lv_color_hex(COL_GREEN), 0);
    lv_obj_set_style_text_font(bat, FONT_ICON, 0);
}

/* ================================================================
 * BIG CLOCK — upper area, NO transform scaling
 * ================================================================ */

static void create_big_clock(lv_obj_t *parent)
{
    /* Clock container: column, centered content */
    lv_obj_t *clk_cont = make_clean_cont(parent);
    lv_obj_set_size(clk_cont, lv_pct(100), LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(clk_cont, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_flex_align(clk_cont, LV_FLEX_ALIGN_CENTER,
                          LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_row(clk_cont, 8, 0);

    /* Big time — native 48px, no scaling, crisp rendering */
    clock_big_label = lv_label_create(clk_cont);
    lv_label_set_text(clock_big_label, "00:00");
    lv_obj_set_style_text_font(clock_big_label, FONT_TITLE, 0);
    lv_obj_set_style_text_color(clock_big_label, lv_color_hex(COL_TEXT), 0);
    lv_obj_set_style_text_letter_space(clock_big_label, 8, 0);

    /* Date — FONT_LABEL below clock (was caption, too small on 8") */
    clock_date_label = lv_label_create(clk_cont);
    lv_label_set_text(clock_date_label, "---");
    lv_obj_set_style_text_font(clock_date_label, FONT_LABEL, 0);
    lv_obj_set_style_text_color(clock_date_label, lv_color_hex(COL_TEXT), 0);
    lv_obj_set_style_text_letter_space(clock_date_label, 2, 0);
}

/* ================================================================
 * CARD CREATION — generic card with frosted glass style
 * ================================================================ */

static lv_obj_t *create_card(lv_obj_t *parent, lv_coord_t w, lv_coord_t h)
{
    lv_obj_t *card = lv_obj_create(parent);
    lv_obj_set_size(card, w, h);
    lv_obj_add_style(card, &style_card, 0);
    lv_obj_set_scrollbar_mode(card, LV_SCROLLBAR_MODE_OFF);
    lv_obj_clear_flag(card, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_clear_flag(card, LV_OBJ_FLAG_CLICKABLE);
    return card;
}

