    lv_obj_set_flex_flow(card, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_flex_align(card, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER,
                          LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_row(card, 8, 0);

    /* AI ring: 48×48 logical (was 64 — shrink to make room for bigger text) */
    lv_obj_t *ring_cont = make_clean_cont(card);
    lv_obj_set_size(ring_cont, DM(48), DM(48));

    lv_obj_t *ring = lv_arc_create(ring_cont);
    lv_obj_set_size(ring, DM(48), DM(48));
    lv_obj_center(ring);
    lv_arc_set_bg_angles(ring, 0, 360);
    lv_arc_set_angles(ring, 0, 300);
    lv_obj_set_style_arc_color(ring, lv_color_hex(COL_BLUE), 0);
    lv_obj_set_style_arc_opa(ring, LV_OPA_20, 0);
    lv_obj_set_style_arc_width(ring, 3, 0);
    lv_obj_remove_flag(ring, LV_OBJ_FLAG_CLICKABLE);

    lv_obj_t *ai_label = lv_label_create(ring_cont);
    lv_label_set_text(ai_label, "AI");
    lv_obj_set_style_text_font(ai_label, FONT_ICON, 0);
    lv_obj_set_style_text_color(ai_label, lv_color_hex(COL_TEXT), 0);
    lv_obj_center(ai_label);

    /* Status — FONT_LABEL, black for readability */
    lv_obj_t *status = lv_label_create(card);
    lv_label_set_text(status, "Ready to help");
    lv_obj_set_style_text_color(status, lv_color_hex(COL_TEXT), 0);
    lv_obj_set_style_text_font(status, FONT_LABEL, 0);

    /* Quote — FONT_LABEL */
    lv_obj_t *quote = lv_label_create(card);
    lv_label_set_text(quote, "Take a short break.");
    lv_obj_set_style_text_color(quote, lv_color_hex(COL_SEC), 0);
    lv_obj_set_style_text_font(quote, FONT_LABEL, 0);
    lv_obj_set_style_text_opa(quote, LV_OPA_60, 0);
}

